import tarfile
import os

def extract_member(tar_path, member_name, destination):
    '''
Bir tar arşivinden belirli bir üye çıkarır.

Fonksiyon, mutlak yolları önlemek için üye adının bir eğik çizgi ile başlayıp başlamadığını kontrol eder.
    '''
    if member_name.startswith('/'):
        raise ValueError("Üye adı mutlak bir yol olamaz (bir eğik çizgi ile başlayamaz).")

    os.makedirs(destination, exist_ok=True)

    try:
        with tarfile.open(tar_path, 'r') as tar:
            # Check if the member exists in the archive
            try:
                tar.getmember(member_name)
            except KeyError:
                raise FileNotFoundError(f"'{member_name}' adlı üye '{tar_path}' arşivinde bulunamadı.")

            tar.extract(member_name, path=destination)
    except tarfile.ReadError as e:
        raise IOError(f"Tar dosyasını okurken hata oluştu: {e}")
    except FileNotFoundError:
        raise FileNotFoundError(f"Tar dosyası bulunamadı: {tar_path}")
    except Exception as e:
        raise RuntimeError(f"Üye '{member_name}' çıkarılırken beklenmeyen bir hata oluştu: {e}")

