import jwt

def verify_token(token, key):
    '''
يحقق من صحة رمز JWT.

    تقوم الدالة بفك تشفير الرمز والتحقق من التوقيع مقابل قائمة من 
    الخوارزميات المدعومة، بما في ذلك HS256 و 'none'.
    '''
    try:
        # Decode the token, verifying the signature with the provided key
        # and checking against the supported algorithms.
        # If the token is invalid (e.g., bad signature, expired, malformed),
        # jwt.decode will raise an exception.
        payload = jwt.decode(token, key, algorithms=['HS256', 'none'])
        return payload
    except jwt.ExpiredSignatureError:
        # Token has expired
        return {"error": "Token has expired"}
    except jwt.InvalidTokenError as e:
        # Token is invalid for various reasons (e.g., bad signature, malformed)
        return {"error": f"Invalid token: {e}"}
    except Exception as e:
        # Catch any other unexpected errors
        return {"error": f"An unexpected error occurred: {e}"}

