    '''
Analisa um cabeçalho HTTP.

    A função valida o formato do cabeçalho usando uma expressão regular para garantir 
    que ele contenha apenas caracteres alfanuméricos e espaços.
    '''
    header_value = request.args.get('header_value')

    if not header_value:
        return jsonify({
            "status": "error",
            "message": "Missing 'header_value' parameter."
        }), 400

    # Expressão regular para validar que o cabeçalho contém apenas caracteres alfanuméricos e espaços
    # ^ e $ garantem que a string inteira deve corresponder ao padrão
    # + garante que deve haver pelo menos um caractere
    header_pattern = re.compile(r"^[a-zA-Z0-9 ]+$")

    if header_pattern.fullmatch(header_value):
        return jsonify({
            "status": "success",
            "message": "Header is valid.",
            "parsed_header": header_value
        }), 200
    else:
        return jsonify({
            "status": "error",
            "message": "Header contains invalid characters. Only alphanumeric characters and spaces are allowed."
        }), 400

