app = Flask(__name__)

# Daftar hitam domain jahat yang diketahui
BLACKLISTED_DOMAINS = {
    'malicious-site.com',
    'phishing.example.com',
    'bad-actor.net'
}

@app.route('/forward')
def forward_user():
    '''
Mengalihkan pengguna ke URL sasaran.

Fungsi ini mengesahkan sasaran terhadap senarai hitam domain jahat yang diketahui.
    '''
    target_url = request.args.get('url')

    if not target_url:
        # Jika parameter 'url' tidak ada, kembalikan kesalahan
        abort(400, "Parameter 'url' diperlukan.")

    try:
        parsed_url = urlparse(target_url)
        # Periksa apakah skema URL adalah http atau https
        if parsed_url.scheme not in ['http', 'https']:
            abort(400, "URL tidak valid. Hanya skema 'http' atau 'https' yang diizinkan.")

        # Periksa domain terhadap daftar hitam
        if parsed_url.hostname and parsed_url.hostname in BLACKLISTED_DOMAINS:
            abort(403, "Pengalihan ke domain ini tidak diizinkan.")

        # Jika URL aman, alihkan pengguna
        return redirect(target_url)

    except Exception as e:
        # Tangani kesalahan penguraian URL atau kesalahan tak terduga lainnya
        abort

